import { Object3D, PlaneGeometry, Mesh, Vector3, Vector2 } from 'three/webgpu';
import {
    MeshBasicNodeMaterial,
    texture,
    uv,
    mul,
    vec2
} from 'three/tsl';
import gsap from 'gsap';
import { createText } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{imageUrl:string}} assets
 * @property {{position:number[],rotation:number[],scale:number[]}} transform
 * @property {string} textContent
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 * @property {Object} colors
 */

/**
 * @typedef {Object} NodeContext
 * @property {{textureLoader: {load:(url:string)=>import('three').Texture}}} textureLoader
 * @property {{fontAtlas: import('three').Texture}} fontAtlas
 * @property {{primitives: Record<string, (obj:Object3D, params:any)=>void>}} primitives
 */

/**
 * Creates a sprite‑like label for a collection card.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
    const root = new Object3D();

    // ---- Transform ---------------------------------------------------------
    const { position = [0, 0, 0], rotation = [0, 0, 0], scale = [1, 1, 1] } = config.transform || {};
    root.position.set(...position);
    root.rotation.set(...rotation);
    root.scale.set(...scale);

    // ---- Main textured plane (billboard) -----------------------------------
    const tex = ctx.textureLoader.load(config.assets.imageUrl);

    // Atlas region dimensions (given) – used for aspect ratio
    const regionWidth = 512;
    const regionHeight = 320;
    const aspect = regionWidth / regionHeight;

    const planeGeom = new PlaneGeometry(aspect, 1);
    const planeMat = new MeshBasicNodeMaterial({ transparent: true });
    // map node with full texture (region starts at 0,0)
    const uvNode = mul(uv(), vec2(1, 1)); // no offset/scale needed for full‑texture region
    planeMat.map = texture(tex, uvNode);
    const planeMesh = new Mesh(planeGeom, planeMat);

    // Simple billboard: copy camera quaternion each render pass
    planeMesh.onBeforeRender = (renderer, scene, camera) => {
        planeMesh.quaternion.copy(camera.quaternion);
    };
    root.add(planeMesh);

    // ---- Text overlay using MSDF font atlas ---------------------------------
    if (config.textContent) {
        // createText returns an Object3D (plane + material) already set up for MSDF rendering
        const textObj = createText({
            text: config.textContent,
            fontAtlas: ctx.fontAtlas,
            // typographic sizing: we base it on a fraction of the plane height
            // 0.2 scene‑units matches the “headline” scale from the design tokens
            size: 0.2,
            color: config.colors?.ink || '#16161d',
            // align centre
            anchorX: 'center',
            anchorY: 'middle'
        });

        // Slightly in front of the image plane to avoid Z‑fighting
        textObj.position.set(0, 0, 0.001);
        root.add(textObj);
    }

    // ---- Apply cinematic primitives (if any) --------------------------------
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const prim of config.cinematicPrimitives) {
            const fn = ctx.primitives[prim.name];
            if (typeof fn === 'function') {
                fn(root, prim.params);
            }
        }
    }

    // ---- UserData -----------------------------------------------------------
    root.userData.handlers = {};

    // Cleanup disposes geometries, materials, textures and any GSAP timelines
    root.userData.cleanup = () => {
        planeGeom.dispose();
        planeMat.dispose();
        if (tex && typeof tex.dispose === 'function') tex.dispose();

        // Dispose possible text resources
        const textChild = root.children.find(c => c !== planeMesh);
        if (textChild && typeof textChild.userData?.cleanup === 'function') {
            textChild.userData.cleanup();
        }

        // Kill all GSAP tweens that might have been attached to this node
        gsap.globalTimeline.clear();
    };

    return root;
}
